UPDATE ui.dashboardquery SET
vcdashboardquery = 'select observations->''txn''->>''class'' as "Class  (CUB or USFB)", observations->''txn''->''attribs''->''pismo_raw''->''fields''->>''account_id'' as	"Account ID", observations->''observations'' -> ''payerVPA'' ->> ''externalId'' as	"Document Number", observations->''txn'' ->''attribs'' -> ''pismo_raw''-> ''fields'' ->> ''last_four_digits'' as	"Last 4 digits of card", observations->''observations'' -> ''payerVPA'' ->> ''vpaName'' as	"Customer Name", dobservationamount as	"Transaction Amount", cast(observations->''txn''->>''ts''  as timestamp with time zone) as	"Authorization Date", cast(observations->''txn''->>''ts'' as timestamp with time zone) as	"Authorization Timestamp", score as	"FRM Score", observations->''txn''->''attribs'' -> ''pismo_raw''-> ''fields'' ->> ''network_score'' as	"Netwrok Score", null as	"Authorization Response Code", triggeredtype.text_  as	"Approved/Declined", observations->''txn''->''attribs''->>''pos_entry_mode'' as	"POS Entry Mode", observations->''txn''->''payee''->>''mcc'' as "Merchant Category Code (MCC)", observations->''observations'' -> ''payeeVPA'' ->> ''vpaName'' as	"Merchant Name", observations->''txn''->''attribs'' -> ''pismo_raw''-> ''fields'' ->> ''merchant_state_or_country_code'' as	"Merchant Location", observations->''txn''->''attribs'' -> ''pismo_raw''-> ''fields'' ->> ''merchant_state_or_country_code'' as	"Card Acceptor Country Code", null as	"Acquirer Country Code", observations->''txn''->''attribs'' ->> ''moto_eci_recurring'' as	"MOTO/ECI/Recurring", observations->''payer''->>''currency'' as	"Issuer Currency Code", observations->''txn''->''attribs'' ->''pismo_row''-> ''fields'' -> ''original_network_data''->>''f61_retrieval_reference_number'' as    "Retrieval Reference Number", vcuniquetransid as   "Transaction ID", observations->''txn''->''attribs''->''pismo_raw''->''fields''->>''terminal_capability'' as "Terminal Capability", observations->''txn''->''attribs''->''pismo_raw''->''fields''->>''transaction_type'' as "Transaction Type", observations->''txn''->''attribs''->>''card_holder_id_method'' as "Cardholder ID Method", observations->''txn''->''attribs''->>''pin_entry_mode'' as  "PIN Entry Capability Code", null as "Terminal Capability Profile", observations->''txn''->''attribs''->>''terminal_type'' as "Terminal Type", observations->''txn''->''attribs'' ->''pismo_row''-> ''fields'' ->> ''tvr_results'' as   "Terminal Verification Results", case when closedby.assignee_ is not null and hiproinst.state_ = ''COMPLETED'' THEN closedby.assignee_ when hiproinst.state_ = ''COMPLETED'' then ''Auto Closed'' when hiproinst.proc_inst_id_ is not null then  ''Open'' END as    "Statused By User ID (42 CS Agent)", CASE WHEN  closedby.assignee_ is not null and hiproinst.state_ = ''COMPLETED'' THEN userinfo.first_ ||'' '' || userinfo.last_ when hiproinst.state_ = ''COMPLETED'' then ''Auto Closed'' when hiproinst.proc_inst_id_ is not null then ''Open'' END as   "Agent Name (42 CS Agent)", hiproinst.end_time_ as   "Alert closed date and time (42 CS Agent)", triggeredtype.text_ as  "Rule type", replace(replace(replace(rulename.text_, ''['', ''''), '']'',''''),''"'','''') as   "Rule Name" from analytics.trans txn left join camunda.act_hi_procinst hiproinst on hiproinst.business_key_ = txn.vcuniquetransid left join camunda.act_hi_varinst triggeredtype  on triggeredtype.proc_inst_id_ = hiproinst.proc_inst_id_ and triggeredtype.name_ = ''triggeredtype'' left join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) left join camunda.act_id_user userinfo on userinfo.id_ = closedby.assignee_ left join camunda.act_hi_varinst rulename on rulename.proc_inst_id_ = hiproinst.proc_inst_id_ and rulename.name_ = ''failedRules'' where dttrxntime between :StartDate  and :EndDate and itenantid = :tenantid limit 25000

'::text WHERE
idashboardqueryid = 123 itenantid in (6, 7, 20, 24);